#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

//! SevenPlus Calculator: window creation, logging, crash reporting and the platform
//! services behind [`calc_ui::Platform`].

mod crash;
mod logging;
mod platform;

use calc_config::Settings;
use calc_theme::ThemeStore;
use calc_ui::{AppInit, MAX_SCALE, MIN_SCALE, Platform, Rect, i18n::tr};
use eframe::egui::{self, Pos2, Vec2};
use eframe::{egui_wgpu, wgpu};
use std::sync::Arc;

const ICON: &[u8] = include_bytes!("../../../assets/icons/sevenplus.png");
/// Third-party licenses generated by `cargo about` (NFR-042).
const LICENSES: &str = include_str!(concat!(env!("OUT_DIR"), "/third-party-licenses.txt"));
/// Wayland app id and X11 WM_CLASS; matches the .desktop file name.
const APP_ID: &str = "io.github.taraskornuta.sevenplus";

fn icon() -> egui::IconData {
    eframe::icon_data::from_png_bytes(ICON).unwrap_or_default()
}

/// Picks a hardware adapter, falling back to a software rasterizer (WARP, llvmpipe,
/// lavapipe) in VMs and remote sessions without a GPU (ARC-003).
fn select_adapter(
    adapters: &[wgpu::Adapter],
    surface: Option<&wgpu::Surface<'_>>,
) -> Result<wgpu::Adapter, String> {
    let rank = |t: wgpu::DeviceType| match t {
        wgpu::DeviceType::DiscreteGpu => 0,
        wgpu::DeviceType::IntegratedGpu => 1,
        wgpu::DeviceType::VirtualGpu => 2,
        wgpu::DeviceType::Other => 3,
        wgpu::DeviceType::Cpu => 4,
    };
    let mut usable: Vec<&wgpu::Adapter> = adapters
        .iter()
        .filter(|a| surface.is_none_or(|s| a.is_surface_supported(s)))
        .collect();
    usable.sort_by_key(|a| rank(a.get_info().device_type));
    let chosen = usable
        .first()
        .ok_or_else(|| "no graphics adapter can draw to this window".to_string())?;
    let info = chosen.get_info();
    if info.device_type == wgpu::DeviceType::Cpu {
        tracing::warn!("no GPU found; using software rendering ({})", info.name);
    } else {
        tracing::info!("rendering with {} ({:?})", info.name, info.backend);
    }
    Ok((*chosen).clone())
}

/// Where to open the window (UI-006, UI-007): the saved position if it is still on a
/// monitor, otherwise centered on the primary monitor. `None` lets the window manager
/// decide (always the case on Wayland, which hides window positions).
fn initial_position(s: &Settings, size_logical: Vec2, monitors: &[Rect]) -> Option<Pos2> {
    let primary = *monitors.first()?;
    let ppp = s
        .window_ppp
        .filter(|p| p.is_finite() && *p > 0.0)
        .unwrap_or(1.0);
    let size = size_logical * ppp;
    if let Some([x, y]) = s.window_pos {
        // The title bar strip must be visible so the window can still be dragged.
        let caption = Rect::from_min_size(Pos2::new(x, y), Vec2::new(size.x, 30.0 * ppp));
        if monitors
            .iter()
            .any(|m| m.intersect(caption).area() >= 30.0 * 30.0)
        {
            return Some(Pos2::new(x / ppp, y / ppp));
        }
    }
    let c = primary.center() - size / 2.0;
    Some(Pos2::new(
        c.x.max(primary.min.x) / ppp,
        c.y.max(primary.min.y) / ppp,
    ))
}

fn main() {
    let _log = logging::init();
    crash::install();
    tracing::info!("SevenPlus {} starting", env!("CARGO_PKG_VERSION"));

    let loaded = Settings::load();
    let settings = loaded.settings;
    let platform = platform::new();
    let store = ThemeStore::new(Some(calc_config::themes_dir()));
    // The OS light/dark preference is only known once the window exists; the first
    // frame switches theme if needed.
    let (theme, _) =
        calc_ui::load_theme(&store, &settings.theme_id(false, platform.high_contrast()));
    let aero = settings.frame == calc_config::FrameStyle::Aero;
    let natural = calc_ui::window_size(&theme, &settings, platform.native_menu());
    let scale = settings.scale.clamp(MIN_SCALE, MAX_SCALE);
    let mut viewport = egui::ViewportBuilder::default()
        .with_title(tr("app-title"))
        .with_app_id(APP_ID)
        .with_icon(icon())
        .with_inner_size(natural * scale)
        .with_min_inner_size(natural * MIN_SCALE)
        .with_resizable(true)
        .with_maximize_button(false)
        .with_decorations(!aero)
        .with_transparent(aero);
    if let Some(pos) = initial_position(&settings, natural * scale, &platform.monitors()) {
        viewport = viewport.with_position(pos);
    }
    let mut options = eframe::NativeOptions {
        viewport,
        ..Default::default()
    };
    if let egui_wgpu::WgpuSetup::CreateNew(setup) = &mut options.wgpu_options.wgpu_setup {
        setup.native_adapter_selector = Some(Arc::new(select_adapter));
    }

    let locale_tag = sys_locale::get_locale().unwrap_or_else(|| "en-US".into());
    let init = AppInit {
        settings,
        settings_warning: loaded.warning,
        locale_tag,
        licenses: LICENSES,
        platform: Box::new(platform),
    };
    let result = eframe::run_native(
        "sevenplus",
        options,
        Box::new(move |cc| Ok(Box::new(calc_ui::App::new(&cc.egui_ctx, init)))),
    );
    if let Err(e) = result {
        tracing::error!("cannot open the window: {e}");
        crash::message(
            &tr("app-name"),
            &format!("Cannot open the calculator window:\n{e}"),
        );
        std::process::exit(1);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn rect(x: f32, y: f32, w: f32, h: f32) -> Rect {
        Rect::from_min_size(Pos2::new(x, y), Vec2::new(w, h))
    }

    #[test]
    fn saved_position_is_kept_when_visible() {
        let s = Settings {
            window_pos: Some([100.0, 100.0]),
            window_ppp: Some(1.0),
            ..Settings::default()
        };
        let m = [rect(0.0, 0.0, 1920.0, 1080.0)];
        assert_eq!(
            initial_position(&s, Vec2::new(228.0, 322.0), &m),
            Some(Pos2::new(100.0, 100.0))
        );
    }

    #[test]
    fn off_screen_position_is_centered_on_primary() {
        // UI-007: saved on a monitor that is no longer connected.
        let s = Settings {
            window_pos: Some([3000.0, 200.0]),
            window_ppp: Some(1.0),
            ..Settings::default()
        };
        let m = [rect(0.0, 0.0, 1920.0, 1080.0)];
        assert_eq!(
            initial_position(&s, Vec2::new(200.0, 300.0), &m),
            Some(Pos2::new(860.0, 390.0))
        );
    }

    #[test]
    fn scaled_monitors_use_logical_units() {
        let s = Settings {
            window_pos: Some([400.0, 300.0]),
            window_ppp: Some(2.0),
            ..Settings::default()
        };
        let m = [rect(0.0, 0.0, 3840.0, 2160.0)];
        assert_eq!(
            initial_position(&s, Vec2::new(228.0, 322.0), &m),
            Some(Pos2::new(200.0, 150.0))
        );
    }

    #[test]
    fn unknown_monitors_leave_it_to_the_window_manager() {
        assert_eq!(
            initial_position(&Settings::default(), Vec2::new(1.0, 1.0), &[]),
            None
        );
    }
}
